parameters.functionCode:
// Extract message from WhatsApp webhook payload
const body = $input.first().json.body;

// Validate it's a message event
if (!body?.entry?.[0]?.changes?.[0]?.value?.messages?.[0]) {
  return [{ json: { skip: true } }];
}

const change = body.entry[0].changes[0].value;
const message = change.messages[0];
const contact = change.contacts?.[0];

// Only process text messages
if (message.type !== 'text') {
  return [{ json: {
    skip: false,
    phoneNumber: message.from,
    response: 'I can only process text messages. Please type your timetable query.',
    isUnsupported: true
  }}];
}

return [{ json: {
  skip: false,
  isUnsupported: false,
  phoneNumber: message.from,
  messageId: message.id,
  query: message.text.body,
  contactName: contact?.profile?.name || 'Student',
  timestamp: message.timestamp,
  phoneNumberId: body.entry[0].changes[0].value.metadata.phone_number_id
}}];

// Query Pre-processing (same logic as web chat)
const input = $input.first().json;
const query = (input.query || '').trim().toLowerCase();

const sectionPatterns = {
  'CSE_SD_Sec_A': /\b(sd|software\s*dev(elopment)?)\b/i,
  'CSE_AIML_Sec_A': /\b(ai|aiml|artificial\s*intelligence|machine\s*learning|ml)\b/i,
  'CSE_CyberSec_Sec_A': /\b(cys|cyber|cyber\s*sec(urity)?)\b/i,
  'CSE_IBM_Sec_A': /\b(ibm)\b/i,
  'CSE_Xebia_Sec_A': /\b(xebia)\b/i
};

const dayPatterns = {
  'Monday': /\b(mon(day)?)\b/i,
  'Tuesday': /\b(tue(sday)?)\b/i,
  'Wednesday': /\b(wed(nesday)?)\b/i,
  'Thursday': /\b(thu(rsday)?)\b/i,
  'Friday': /\b(fri(day)?)\b/i,
  'Saturday': /\b(sat(urday)?)\b/i
};

let detectedSection = null;
let detectedDay = null;

for (const [tab, pattern] of Object.entries(sectionPatterns)) {
  if (pattern.test(query)) {
    detectedSection = tab;
    break;
  }
}

for (const [day, pattern] of Object.entries(dayPatterns)) {
  if (pattern.test(query)) {
    detectedDay = day;
    break;
  }
}

return [{
  json: {
    ...input,
    originalQuery: query,
    detectedSection,
    detectedDay
  }
}];

